// Performance monitoring script
window.addEventListener('load', function() {
 setTimeout(function() {
 var t = performance.timing;
 var pageLoadTime = t.loadEventEnd - t.navigationStart;
 var dnsTime = t.domainLookupEnd - t.domainLookupStart;
 var tcpTime = t.connectEnd - t.connectStart;
 var ttfb = t.responseStart - t.requestStart;
 var domLoadTime = t.domComplete - t.domLoading;

 console.log('Page load time: ' + pageLoadTime + 'ms');
 console.log('DNS lookup time: ' + dnsTime + 'ms');
 console.log('TCP connection time: ' + tcpTime + 'ms');
 console.log('Time to first byte: ' + ttfb + 'ms');
 console.log('DOM processing time: ' + domLoadTime + 'ms');

 // Collect Core Web Vitals
 if (typeof web_vitals !== 'undefined') {
 web_vitals.getCLS(console.log);
 web_vitals.getFID(console.log);
 web_vitals.getLCP(console.log);
 }
 }, 0);
});
